  "jsonSchema": {
    "type": "object",
    "properties": {
      "category": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string"
          },
          "subcategories": {
            "type": "array",
            "items": {
              "$ref": "#/properties/category"
            }
          }
        },
        "required": [
          "name",
          "subcategories"
        ],
        "additionalProperties": false
      }
    },
    "required": [
      "category"
    ],
    "additionalProperties": false,
    "$schema": "http://json-schema.org/draft-07/schema#"
  }
}
```


